//! Mechanical tests across the ladder: fracture toughness (the Griffith fold)
//! and yield from the plasticity fold.
//!
//! The fracture test is the Griffith energy balance `K_IC = sqrt(2 γ_s E')`.
//! For the fully atomistic material (LJ argon) both inputs are generated by
//! the same pair potential: `γ_s` from the broken-bond lattice sum of
//! [`materials::defects`] and `E, ν` from the Cauchy–Born stiffness. For the
//! ductile metals the measured single-crystal constants and a handbook
//! surface energy are used, and the result is compared with the measured
//! `K_IC` — where it fails by two orders of magnitude, because LEFM/Griffith
//! describes cleavage, not the dislocation-mediated tearing that sets the
//! toughness of a ductile metal (Rice 1992).
//!
//! The yield test uses the Peierls–Nabarro fold where a pair potential
//! supplies the γ-surface (LJ argon); for the metals only the handbook yield
//! stress exists and the report says so.

use crate::{Level, Material, Measurement};
use materials::defects::broken_bond_surface_energy;
use materials::fracture::{griffith_anisotropic_kic, griffith_plane_strain};
use materials::lattice::Lattice;
use materials::plasticity::{
    fcc_burgers, fcc_slip_plane_spacing, fault_plane_strength, peierls_nabarro,
    sinusoidal_core_width, TAYLOR_FCC,
};
use materials::polycrystal::hill;
use materials::potential::{relax_cutoff, LennardJones};

/// Measured surface energies and handbook fracture toughness of the metals,
/// per unit area (J/m²) and `K_IC` (Pa·√m).
struct FractureRef {
    /// Surface energy J/m².
    gamma_s: f64,
    gamma_source: &'static str,
    /// Measured `K_IC` in Pa·√m; `NaN` when there is no handbook value.
    kic_ref: f64,
    kic_source: &'static str,
    /// Unstable stacking-fault energy `γ_us` (J/m²), `NaN` if unknown.
    gamma_us: f64,
}

fn fracture_ref(name: &str) -> FractureRef {
    match name {
        // Cu: solid surface energy ≈ 1.8 J/m² (estimate; the 0 K (111)
        // surface energy is 2.2, the liquid surface tension at melting
        // 1.3). Ductile K_IC ≈ 100 MPa√m, Callister, Materials Science and
        // Engineering (typical annealed Cu). γ_us ≈ 0.16 J/m² (DFT estimate
        // for Cu, e.g. the unstable SFE compilation of Schoeck).
        "Cu" => FractureRef {
            gamma_s: 1.8,
            gamma_source: "estimate; solid Cu surface energy 1.3–2.2 J/m²",
            kic_ref: 100.0e6,
            kic_source: "annealed Cu, Callister, Materials Science and Engineering (typical K_IC)",
            gamma_us: 0.16,
        },
        // Al: surface energy ≈ 1.2 J/m², K_IC ≈ 35 MPa√m (Callister).
        "Al" => FractureRef {
            gamma_s: 1.2,
            gamma_source: "estimate; solid Al surface energy ≈ 1.1–1.2 J/m²",
            kic_ref: 35.0e6,
            kic_source: "annealed Al, Callister, Materials Science and Engineering (typical K_IC)",
            gamma_us: 0.16,
        },
        // LJ argon: generated atomistically below.
        _ => FractureRef {
            gamma_s: f64::NAN,
            gamma_source: "atomistic broken-bond sum",
            kic_ref: f64::NAN,
            kic_source: "no handbook value for the classical LJ crystal",
            gamma_us: 0.4226,
        },
    }
}

/// Unit of `ε/σⁿ` for argon, in SI, with `n = 2` (energy per area).
fn argon_energy_per_area_unit() -> f64 {
    md::argon::epsilon_j() / md::argon::SIGMA_M.powi(2)
}

/// Atomistic surface energy of the LJ fcc crystal in `ε/σ²` for a given
/// normal (broken-bond sum at `rc = 12σ`, matching [`crate::atomistic`]).
pub fn argon_surface_energy_reduced(normal: [f64; 3]) -> f64 {
    let lj = LennardJones::new(1.0, 1.0);
    let raw = relax_cutoff(&Lattice::fcc(1.0), &lj, 12.0, 0.9, 1.8);
    let lat = Lattice::fcc(raw.scale);
    broken_bond_surface_energy(&lat, &lj, 12.0, normal)
}

/// The complete fracture test for one material.
pub fn fracture(mat: &Material) -> Vec<Measurement> {
    let mut out = Vec::new();
    let r = fracture_ref(mat.name);
    let moduli = hill(&mat.c);
    let (e, nu) = (moduli.young(), moduli.poisson());

    match mat.name {
        "Cu" | "Al" => {
            let kic = griffith_plane_strain(r.gamma_s, e, nu);
            out.push(Measurement::new(
                mat.name,
                "fracture (Griffith)",
                Level::SingleCrystal,
                "K_IC (Griffith)",
                kic / 1e6,
                r.kic_ref / 1e6,
                "MPa·m^0.5",
                false,
                &format!(
                    "Griffith cleavage balance with γ_s = {:.2} J/m² ({}) and the Hill moduli; \
                     the measured ductile toughness is set by dislocation emission/tearing, not \
                     cleavage, so the fold is NOT valid. Rice ratio γ_us/γ_s = {:.3} < 0.25 \
                     predicts emission (measured reference: {}).",
                    r.gamma_s, r.gamma_source, r.gamma_us / r.gamma_s, r.kic_source
                ),
            ));
        }
        _ => {
            // Atomistic route: γ_s from the lattice sum, moduli from the
            // Cauchy–Born tensor. Reference: the anisotropic Stroh Irwin
            // matrix from the same atomistic inputs (an independent path).
            let gamma_red = argon_surface_energy_reduced([1.0, 1.0, 1.0]);
            let gamma_si = gamma_red * argon_energy_per_area_unit();
            let kic_iso = griffith_plane_strain(gamma_si, e, nu);
            let kic_aniso = griffith_anisotropic_kic(&mat.c, gamma_si);
            out.push(Measurement::new(
                mat.name,
                "fracture (Griffith)",
                Level::Atomistic,
                "K_IC (atomistic γ_s)",
                kic_iso / 1e6,
                kic_aniso / 1e6,
                "MPa·m^0.5",
                (kic_iso / kic_aniso - 1.0).abs() < 0.10,
                &format!(
                    "γ_s(111) = {:.4} J/m² from the broken-bond LJ lattice sum, E,ν from the \
                     Cauchy–Born tensor; reference is the anisotropic Stroh Irwin-matrix \
                     toughness. The 5–6 % gap is the Zener anisotropy A = {:.2} of LJ fcc.",
                    gamma_si,
                    mat.zener()
                ),
            ));
            // Exact 2D atomistic Griffith threshold: K_G = sqrt(2 γ_2D E_2D)
            // with γ_2D = 1/a0 and E_2D = 65.987 ε/σ² (analysis/fracture.md).
            let a0 = 2.0_f64.powf(1.0 / 6.0);
            let e2d = 65.9870;
            let gamma2d = 1.0 / a0;
            let k_g = (2.0 * gamma2d * e2d).sqrt();
            let k_g_ref = 10.8432;
            out.push(Measurement::new(
                mat.name,
                "fracture (atomistic 2D)",
                Level::Atomistic,
                "K_G (2D sheet)",
                k_g,
                k_g_ref,
                "ε/σ^{3/2}",
                (k_g / k_g_ref - 1.0).abs() < 1e-5,
                "closed-form 2D nearest-neighbour LJ Griffith threshold \
                 sqrt(2 γ_2D E_2D) vs the exact value in analysis/fracture.md; the finite \
                 atomistic crack advances at the geometric factor K_c/K_G ≈ 1.48",
            ));
            // Peierls–Nabarro plasticity fold: the classical core width is
            // compared with the width implied by the atomistic γ_us.
            let g = moduli.shear;
            // fcc LJ equilibrium (analysis/defects.md): a = 1.5417373 σ,
            // r_nn = 1.0901729 σ, so b = a/√2 and d = a/√3.
            let a0 = 1.541_737_3;
            let b = fcc_burgers(a0);
            let d = fcc_slip_plane_spacing(a0);
            let pn = peierls_nabarro(g, nu, b, d);
            let sigma_p = pn.sigma_p;
            let sigma_p_ref = 3.296 * md::argon::pressure_unit();
            out.push(Measurement::new(
                mat.name,
                "yield (Peierls–Nabarro)",
                Level::Atomistic,
                "σ_P",
                sigma_p / 1e6,
                sigma_p_ref / 1e6,
                "MPa",
                (sigma_p / sigma_p_ref - 1.0).abs() < 0.02,
                "classical Peierls stress from the Cauchy–Born Hill moduli and the fcc slip \
                 geometry, vs the value 3.296 ε/σ³ = 0.081 G in analysis/defects.md. PN is an \
                 order-of-magnitude closure: the measured γ_us implies a core 6.5× wider.",
            ));
            let zeta_implied = sinusoidal_core_width(
                g,
                nu,
                b * md::argon::SIGMA_M,
                0.4226 * argon_energy_per_area_unit(),
            ) / md::argon::SIGMA_M;
            out.push(Measurement::new(
                mat.name,
                "yield (Peierls–Nabarro)",
                Level::Atomistic,
                "core width ζ (classical)",
                pn.zeta,
                zeta_implied,
                "σ",
                false,
                &format!(
                    "classical width d/(2(1−ν)) = {:.3} σ vs the width {:.2} σ implied by the \
                     measured atomistic γ_us = 0.4226 ε/σ². The exponential PN stress is \
                     exponentially sensitive to ζ, so the fold is reported invalid for a \
                     quantitative yield stress.",
                    pn.zeta, zeta_implied
                ),
            ));
            let sigma_ideal = fault_plane_strength(0.4226, b) * md::argon::pressure_unit();
            out.push(Measurement::new(
                mat.name,
                "yield (ideal strength)",
                Level::Atomistic,
                "fault-plane strength",
                sigma_ideal / 1e6,
                1.22 * md::argon::pressure_unit() / 1e6,
                "MPa",
                (sigma_ideal / (1.22 * md::argon::pressure_unit()) - 1.0).abs() < 0.01,
                "ideal shear strength π γ_us/b with the atomistic γ_us = 0.4226 ε/σ², vs the \
                 1.22 ε/σ³ = 0.030 G tabulated in analysis/defects.md",
            ));
        }
    }
    out
}

/// Yield/hardness summary for the metals, where only the handbook value is
/// available. Kept separate so the report can show the rung explicitly.
pub fn metal_yield(mat: &Material) -> Vec<Measurement> {
    if !mat.yield_stress.is_finite() {
        return Vec::new();
    }
    // Taylor factor times a representative single-crystal CRSS from the
    // handbook yield: this is the inverse of the fold, reported so the
    // reader sees that the continuum closure is the measured number.
    let tau_crss = mat.yield_stress / TAYLOR_FCC;
    vec![Measurement::new(
        mat.name,
        "yield (continuum)",
        Level::Polycrystal,
        "σ_y",
        mat.yield_stress / 1e6,
        mat.yield_stress / 1e6,
        "MPa",
        true,
        &format!(
            "handbook polycrystal yield; the plasticity fold would predict M_T τ_CRSS with the \
             Taylor factor M_T = {:.2}, giving an implied CRSS of {:.1} MPa. The atomistic CRSS \
             is unavailable for a metal without a pair potential, so the measured value is the \
             bottom rung. Source: {}",
            TAYLOR_FCC,
            tau_crss / 1e6,
            mat.yield_source
        ),
    )]
}
